def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]
    opp_c = opp.count('C')
    opp_d = n - opp_c

    if n < 3:
        return 'C'

    recent_opp = opp[-8:] if n >= 8 else opp
    recent_len = len(recent_opp)
    recent_d = recent_opp.count('D')
    recent_c = recent_len - recent_d

    run_c = 0
    for a in reversed(opp):
        if a == 'C':
            run_c += 1
        else:
            break
    run_d = 0
    for a in reversed(opp):
        if a == 'D':
            run_d += 1
        else:
            break

    my_run_d = 0
    for a in reversed(me):
        if a == 'D':
            my_run_d += 1
        else:
            break

    early_nice = opp[:n].count('C') >= n - 1

    if opp_d == 0:
        if n == 99:
            return 'D'
        if early_nice and run_c >= 3 and n >= 20:
            if rng.random() < 0.08:
                return 'D'
        return 'C'

    if n == 99:
        if opp_d * 3 >= n * 2 and last_opp == 'D':
            return 'D'
        if recent_d >= recent_len * 0.5:
            return 'D'
        return 'C'

    if recent_len >= 6 and recent_d >= recent_len - 1 and opp_c <= 2:
        return 'D'

    if run_d >= 2 and opp_d * 2 >= n:
        if run_d >= 4:
            return 'D'
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if last_me == 'D':
            if run_d >= 4:
                if rng.random() < 0.12:
                    return 'C'
                return 'D'
            if my_run_d >= 3 and rng.random() < 0.25:
                return 'C'
            return 'D'
        else:
            if recent_d >= 3 and recent_len >= 5:
                return 'D'
            if opp_d >= 4 and opp_d * 2 >= n:
                return 'D'
            if rng.random() < 0.1:
                return 'C'
            return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            if run_c >= 2 and recent_d <= 1:
                return 'C'
            if rng.random() < 0.85:
                return 'C'
            return 'D'
        if recent_d == 0 and recent_len >= 4:
            return 'C'
        if recent_d <= recent_len * 0.25:
            if run_c >= 6 and n >= 15 and rng.random() < 0.1:
                return 'D'
            return 'C'
        if recent_c >= 2 and rng.random() < 0.75:
            return 'C'
        return 'D'

    return 'C'
